import json
from datetime import datetime, timezone
from pathlib import Path

from mock_api import TRACE, search
from timezone_defaults import DEFAULT_TIMEZONE, MISSING_TZ_POLICY


def _error(param, message, payload, normalized=None):
    """Build a JSON-friendly validation error without changing the input."""
    result = {"param": param, "error": message, "payload": payload}
    if normalized is not None:
        result["normalized"] = normalized
    return result


def _parse_bound(payload, param, errors):
    value = payload.get(param)
    if not isinstance(value, str) or not value.strip():
        errors.append(_error(param, "must be a non-empty ISO 8601 string", payload))
        return None

    try:
        # Python 3.10's parser does not accept the ISO 8601 ``Z`` suffix.
        parser_value = value[:-1] + "+00:00" if value.endswith(("Z", "z")) else value
        parsed = datetime.fromisoformat(parser_value)
    except (TypeError, ValueError):
        errors.append(_error(param, "must be a valid ISO 8601 timestamp", payload))
        return None

    if parsed.tzinfo is None:
        # The migration contract explicitly defines naive timestamps as UTC.
        parsed = parsed.replace(tzinfo=DEFAULT_TIMEZONE)
    return parsed


def _utc_text(value):
    return value.astimezone(timezone.utc).isoformat()


def validate_range(payload):
    """Return every local validation error for one query."""
    if not isinstance(payload, dict):
        return [_error("query", "must be an object", payload)]

    errors = []
    start = _parse_bound(payload, "start_date", errors)
    end = None
    if "end_date" in payload:
        end = _parse_bound(payload, "end_date", errors)

    # An omitted end_date is intentionally valid. Ordering checks only apply
    # once both independently parsed endpoints are available.
    if start is None or end is None:
        return errors

    normalized = {
        "start_utc": _utc_text(start),
        "end_utc": _utc_text(end),
        "naive_timezone_policy": MISSING_TZ_POLICY,
        "default_timezone": "UTC",
    }
    if end.astimezone(timezone.utc) < start.astimezone(timezone.utc):
        errors.append(_error(
            "date_range",
            "end_date must not be before start_date after UTC normalization",
            payload,
            normalized,
        ))

    # A fall-back overlap is ambiguous to the service when the repeated local
    # hour uses different offsets and its wall-clock end is earlier. This is
    # deliberately checked in addition to (not instead of) UTC ordering.
    start_local = start.replace(tzinfo=None)
    end_local = end.replace(tzinfo=None)
    if (
        start.date() == end.date()
        and start.hour == end.hour
        and start.utcoffset() != end.utcoffset()
        and end_local < start_local
    ):
        errors.append(_error(
            "date_range",
            "ambiguous fall-back DST range: end wall-clock time is earlier",
            payload,
            normalized,
        ))
    return errors


def process_queries(path):
    TRACE.clear()
    payload = json.loads(Path(path).read_text(encoding="utf-8"))
    accepted = []
    rejected = []
    for index, query in enumerate(payload):
        errors = validate_range(query)
        if errors:
            rejected.append({"index": index, "errors": errors, "original": query})
            continue
        accepted.append(search(query))
    return {"accepted": accepted, "rejected": rejected, "trace": list(TRACE)}

